def load_numbers(name):
    numbers = []
    skipped = 0
    try:
        with open(name) as f:
            for line in f:
                try:
                    numbers.append(int(line))
                except ValueError:
                    skipped = skipped + 1
    except FileNotFoundError:
        print("no", name, "yet")
    return numbers, skipped

print(load_numbers("stats.txt"))
print(load_numbers("other.txt"))

